export interface Shipment {
  id: string;
  status: 'label_created' | 'in_transit' | 'delivered';
  updatedAt: string;
}

export interface ShipmentRequest {
  params: { shipmentId?: string };
}

export interface ShipmentResponse {
  status(code: number): void;
  json(payload: unknown): void;
}

export type Next = (error?: unknown) => void;

export function getShipmentHandler(
  findShipment: (shipmentId: string) => Promise<Shipment | null>,
) {
  return async (req: ShipmentRequest, res: ShipmentResponse, next: Next): Promise<void> => {
    const shipmentId = req.params.shipmentId?.trim();
    if (!shipmentId) {
      res.status(400);
      res.json({ error: 'shipmentId is required' });
      return;
    }

    try {
      const shipment = await findShipment(shipmentId);
      if (!shipment) {
        res.status(404);
        res.json({ error: 'Shipment not found' });
        return;
      }

      res.status(200);
      res.json({ shipment });
    } catch (error) {
      next(error);
    }
  };
}

