import { describe, expect, it, vi } from 'vitest';
import { getShipmentHandler } from './handler';

describe('getShipmentHandler', () => {
  it('returns the shipment when the repository finds it', async () => {
    const shipment = { id: 'shp_7316', status: 'in_transit' as const, updatedAt: '2031-06-03T14:20:00Z' };
    const findShipment = vi.fn().mockResolvedValue(shipment);
    const handler = getShipmentHandler(findShipment);
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler({ params: { shipmentId: 'shp_7316' } }, res, next);

    expect(findShipment).toHaveBeenCalledWith('shp_7316');
    expect(res.status).toHaveBeenCalledWith(200);
    expect(res.json).toHaveBeenCalledWith({ shipment });
    expect(next).not.toHaveBeenCalled();
  });

  it('returns 400 and skips lookup when the path parameter is blank', async () => {
    const findShipment = vi.fn();
    const handler = getShipmentHandler(findShipment);
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler({ params: { shipmentId: '   ' } }, res, next);

    expect(res.status).toHaveBeenCalledWith(400);
    expect(res.json).toHaveBeenCalledWith({ error: 'shipmentId is required' });
    expect(findShipment).not.toHaveBeenCalled();
    expect(next).not.toHaveBeenCalled();
  });

  it('returns 404 when the repository has no matching shipment', async () => {
    const findShipment = vi.fn().mockResolvedValue(null);
    const handler = getShipmentHandler(findShipment);
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler({ params: { shipmentId: 'shp_missing' } }, res, next);

    expect(findShipment).toHaveBeenCalledWith('shp_missing');
    expect(res.status).toHaveBeenCalledWith(404);
    expect(res.json).toHaveBeenCalledWith({ error: 'Shipment not found' });
    expect(next).not.toHaveBeenCalled();
  });
});

