export interface CreateReservationInput {
  roomId: string;
  startAt: string;
  endAt: string;
}

export interface Reservation extends CreateReservationInput {
  id: string;
}

export interface ReservationRequest {
  body: unknown;
}

export interface ReservationResponse {
  status(code: number): void;
  json(payload: unknown): void;
}

export type Next = (error?: unknown) => void;

export function createReservationHandler(
  createReservation: (input: CreateReservationInput) => Promise<Reservation>,
) {
  return async (req: ReservationRequest, res: ReservationResponse, next: Next): Promise<void> => {
    const body = req.body as Partial<CreateReservationInput> | null;
    if (
      !body ||
      typeof body.roomId !== 'string' || body.roomId.trim() === '' ||
      typeof body.startAt !== 'string' || body.startAt.trim() === '' ||
      typeof body.endAt !== 'string' || body.endAt.trim() === ''
    ) {
      res.status(400);
      res.json({ error: 'roomId, startAt, and endAt are required' });
      return;
    }

    try {
      const reservation = await createReservation({
        roomId: body.roomId,
        startAt: body.startAt,
        endAt: body.endAt,
      });
      res.status(201);
      res.json({ reservation });
    } catch (error) {
      next(error);
    }
  };
}

