import { describe, expect, it, vi } from 'vitest';
import { createReservationHandler } from './handler';

describe('createReservationHandler', () => {
  it('creates a reservation and returns it with status 201', async () => {
    const reservation = {
      id: 'rsv_4821',
      roomId: 'room_north_3',
      startAt: '2031-04-12T09:00:00Z',
      endAt: '2031-04-12T10:30:00Z',
    };
    const createReservation = vi.fn().mockResolvedValue(reservation);
    const handler = createReservationHandler(createReservation);
    const req = { body: { roomId: 'room_north_3', startAt: '2031-04-12T09:00:00Z', endAt: '2031-04-12T10:30:00Z' } };
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler(req, res, next);

    expect(createReservation).toHaveBeenCalledWith(req.body);
    expect(res.status).toHaveBeenCalledWith(201);
    expect(res.json).toHaveBeenCalledWith({ reservation });
    expect(next).not.toHaveBeenCalled();
  });

  it('rejects a request with a missing room identifier without calling the service', async () => {
    const createReservation = vi.fn();
    const handler = createReservationHandler(createReservation);
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler({ body: { startAt: '2031-04-12T09:00:00Z', endAt: '2031-04-12T10:30:00Z' } }, res, next);

    expect(res.status).toHaveBeenCalledWith(400);
    expect(res.json).toHaveBeenCalledWith({ error: 'roomId, startAt, and endAt are required' });
    expect(createReservation).not.toHaveBeenCalled();
    expect(next).not.toHaveBeenCalled();
  });

  it('forwards service failures to error middleware', async () => {
    const failure = new Error('reservation store unavailable');
    const createReservation = vi.fn().mockRejectedValue(failure);
    const handler = createReservationHandler(createReservation);
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler({ body: { roomId: 'room_north_3', startAt: '2031-04-12T09:00:00Z', endAt: '2031-04-12T10:30:00Z' } }, res, next);

    expect(next).toHaveBeenCalledWith(failure);
    expect(res.status).not.toHaveBeenCalled();
    expect(res.json).not.toHaveBeenCalled();
  });
});

