export interface StockAdjustment {
  sku: string;
  delta: number;
  expectedVersion: number;
}

export interface InventoryRecord {
  sku: string;
  quantity: number;
  version: number;
}

export interface AdjustmentRequest {
  params: { sku?: string };
  body: unknown;
}

export interface AdjustmentResponse {
  status(code: number): void;
  json(payload: unknown): void;
}

export type Next = (error?: unknown) => void;

export class InsufficientStockError extends Error {}
export class VersionConflictError extends Error {}

export function adjustInventoryHandler(
  adjustStock: (input: StockAdjustment) => Promise<InventoryRecord | null>,
) {
  return async (req: AdjustmentRequest, res: AdjustmentResponse, next: Next): Promise<void> => {
    const sku = req.params.sku?.trim();
    const body = req.body as { delta?: unknown; expectedVersion?: unknown } | null;

    if (
      !sku ||
      !body ||
      typeof body.delta !== 'number' || !Number.isInteger(body.delta) || body.delta === 0 ||
      typeof body.expectedVersion !== 'number' || !Number.isInteger(body.expectedVersion) || body.expectedVersion < 0
    ) {
      res.status(400);
      res.json({ error: 'A SKU, non-zero integer delta, and non-negative integer expectedVersion are required' });
      return;
    }

    try {
      const record = await adjustStock({ sku, delta: body.delta, expectedVersion: body.expectedVersion });
      if (!record) {
        res.status(404);
        res.json({ error: 'Inventory item not found' });
        return;
      }

      res.status(200);
      res.json({ item: record });
    } catch (error) {
      if (error instanceof InsufficientStockError) {
        res.status(409);
        res.json({ error: 'The adjustment would reduce stock below zero', code: 'INSUFFICIENT_STOCK' });
        return;
      }
      if (error instanceof VersionConflictError) {
        res.status(409);
        res.json({ error: 'Inventory item was updated by another request', code: 'VERSION_CONFLICT' });
        return;
      }
      next(error);
    }
  };
}

