import { describe, expect, it, vi } from 'vitest';
import { adjustInventoryHandler, InsufficientStockError } from './handler';

describe('adjustInventoryHandler', () => {
  it('applies a valid adjustment using the supplied version', async () => {
    const item = { sku: 'valve-seat-18', quantity: 26, version: 8 };
    const adjustStock = vi.fn().mockResolvedValue(item);
    const handler = adjustInventoryHandler(adjustStock);
    const req = { params: { sku: 'valve-seat-18' }, body: { delta: 4, expectedVersion: 7 } };
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler(req, res, next);

    expect(adjustStock).toHaveBeenCalledWith({ sku: 'valve-seat-18', delta: 4, expectedVersion: 7 });
    expect(res.status).toHaveBeenCalledWith(200);
    expect(res.json).toHaveBeenCalledWith({ item });
    expect(next).not.toHaveBeenCalled();
  });

  it('rejects a zero delta before calling the inventory operation', async () => {
    const adjustStock = vi.fn();
    const handler = adjustInventoryHandler(adjustStock);
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler({ params: { sku: 'valve-seat-18' }, body: { delta: 0, expectedVersion: 7 } }, res, next);

    expect(res.status).toHaveBeenCalledWith(400);
    expect(res.json).toHaveBeenCalledWith({ error: 'A SKU, non-zero integer delta, and non-negative integer expectedVersion are required' });
    expect(adjustStock).not.toHaveBeenCalled();
  });

  it('maps an insufficient-stock business error to a conflict response', async () => {
    const adjustStock = vi.fn().mockRejectedValue(new InsufficientStockError('quantity cannot become negative'));
    const handler = adjustInventoryHandler(adjustStock);
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler({ params: { sku: 'valve-seat-18' }, body: { delta: -30, expectedVersion: 7 } }, res, next);

    expect(res.status).toHaveBeenCalledWith(409);
    expect(res.json).toHaveBeenCalledWith({ error: 'The adjustment would reduce stock below zero', code: 'INSUFFICIENT_STOCK' });
    expect(next).not.toHaveBeenCalled();
  });

  it('returns 404 when the SKU is not present', async () => {
    const adjustStock = vi.fn().mockResolvedValue(null);
    const handler = adjustInventoryHandler(adjustStock);
    const res = { status: vi.fn(), json: vi.fn() };
    const next = vi.fn();

    await handler({ params: { sku: 'unknown-part' }, body: { delta: 2, expectedVersion: 0 } }, res, next);

    expect(res.status).toHaveBeenCalledWith(404);
    expect(res.json).toHaveBeenCalledWith({ error: 'Inventory item not found' });
  });
});
